  "inlineSchema": "// FocusForest — Prisma Schema\n// Run `npx prisma validate` after every change.\n// Run `npx prisma migrate dev` to apply migrations.\n//\n// DB: Supabase PostgreSQL\n// ORM: Prisma 5+\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ---------------------------------------------------------------------------\n// USERS\n// ---------------------------------------------------------------------------\n// Mirrors the Supabase Auth user. Created via a trigger or manually on signup.\n// utc_offset: user's local UTC offset in minutes (e.g. +330 for IST, -300 for EST)\n// Used by the midnight cron to batch users by local midnight.\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  name      String\n  avatarUrl String?  @map(\"avatar_url\")\n  utcOffset Int      @default(0) @map(\"utc_offset\") // minutes from UTC\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  sessions          Session[]\n  dailyTrees        DailyTree[]\n  streak            Streak?\n  groupsAdmin       Group[]            @relation(\"GroupAdmin\")\n  groupMemberships  GroupMember[]\n  pushSubscriptions PushSubscription[]\n\n  @@map(\"users\")\n}\n\n// ---------------------------------------------------------------------------\n// SESSIONS\n// ---------------------------------------------------------------------------\n// One row per completed focus session.\n// client_session_id: UUID generated by the client. Used to deduplicate retries.\n// stage_progress: server-computed value — NEVER set by the client.\n// task_status: what the user chose at the end-of-session popup.\n\nmodel Session {\n  id              String     @id @default(uuid())\n  userId          String     @map(\"user_id\")\n  variant         Variant\n  focusMinutes    Int        @map(\"focus_minutes\")\n  taskText        String?    @map(\"task_text\")\n  taskStatus      TaskStatus @default(none) @map(\"task_status\")\n  stageProgress   Float      @map(\"stage_progress\") // server-computed: (focus_minutes / 25) × task_multiplier\n  clientSessionId String     @unique @map(\"client_session_id\") // UUID for deduplication\n  createdAt       DateTime   @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n  @@map(\"sessions\")\n}\n\n// ---------------------------------------------------------------------------\n// DAILY TREES\n// ---------------------------------------------------------------------------\n// One row per user per calendar day. Created as a seed on the first session of the day.\n// stage: 0 (seed) → 4 (full tree). Capped at 4.\n// glow_level: 0–4, computed as tasks_completed / total_sessions_today.\n// is_bare: true if finalised with 0 sessions (missed day). Cannot be backdated.\n// finalised_at: set by the midnight cron job.\n\nmodel DailyTree {\n  id               String    @id @default(uuid())\n  userId           String    @map(\"user_id\")\n  date             DateTime  @db.Date // local calendar date (no time, no timezone)\n  stage            Int       @default(0) // 0–4\n  glowLevel        Int       @default(0) @map(\"glow_level\") // 0–4\n  totalSessions    Int       @default(0) @map(\"total_sessions\")\n  sessionsWithTask Int       @default(0) @map(\"sessions_with_task\")\n  isBare           Boolean   @default(false) @map(\"is_bare\")\n  finalisedAt      DateTime? @map(\"finalised_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date]) // one tree per user per day\n  @@index([userId, date])\n  @@map(\"daily_trees\")\n}\n\n// ---------------------------------------------------------------------------\n// STREAKS\n// ---------------------------------------------------------------------------\n// One row per user. Created on first session. Updated by midnight cron.\n// last_active_date: the most recent calendar day with at least 1 session.\n// Used to determine if the streak was broken.\n\nmodel Streak {\n  id             String   @id @default(uuid())\n  userId         String   @unique @map(\"user_id\")\n  currentStreak  Int      @default(0) @map(\"current_streak\")\n  longestStreak  Int      @default(0) @map(\"longest_streak\")\n  lastActiveDate DateTime @map(\"last_active_date\") @db.Date\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"streaks\")\n}\n\n// ---------------------------------------------------------------------------\n// GROUPS\n// ---------------------------------------------------------------------------\n// Max 5 members including creator. inviteCode is a 6-digit alphanumeric string.\n// member_count is a denormalised counter kept in sync via triggers or manually.\n// Once member_count == 5, the invite link is disabled.\n\nmodel Group {\n  id          String   @id @default(uuid())\n  name        String\n  adminUserId String   @map(\"admin_user_id\")\n  inviteCode  String   @unique @map(\"invite_code\") // 6-character alphanumeric\n  memberCount Int      @default(1) @map(\"member_count\") // max 5\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  admin   User          @relation(\"GroupAdmin\", fields: [adminUserId], references: [id])\n  members GroupMember[]\n\n  @@map(\"groups\")\n}\n\n// ---------------------------------------------------------------------------\n// GROUP MEMBERS\n// ---------------------------------------------------------------------------\n\nmodel GroupMember {\n  id       String   @id @default(uuid())\n  groupId  String   @map(\"group_id\")\n  userId   String   @map(\"user_id\")\n  joinedAt DateTime @default(now()) @map(\"joined_at\")\n\n  group Group @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([groupId, userId]) // can't join same group twice\n  @@map(\"group_members\")\n}\n\n// ---------------------------------------------------------------------------\n// PUSH SUBSCRIPTIONS\n// ---------------------------------------------------------------------------\n// Web Push API subscription objects. Stored per device per user.\n// p256dh and auth are the ECDH public key and auth secret from the browser PushSubscription.\n\nmodel PushSubscription {\n  id        String   @id @default(uuid())\n  userId    String   @map(\"user_id\")\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"push_subscriptions\")\n}\n\n// ---------------------------------------------------------------------------\n// ENUMS\n// ---------------------------------------------------------------------------\n\nenum Variant {\n  sprint\n  classic\n  deep_work\n  flow\n  custom\n}\n\nenum TaskStatus {\n  completed\n  carried\n  none\n}\n",
